468	// ─── backward GEMMs via the Sm90 collective (TMA + WGMMA) ───────────────
469	// Two thin element-type dispatchers that pick the real-CUTLASS runner
470	// (half/bf16) or the TF32 runner (float read as tfloat32_t) for the BT
471	// (B-or-Bᵀ) and AT (Aᵀ·B) collective builders in mma.cuh. They keep the
472	// dgrad/wgrad launchers below dtype-agnostic without re-deriving the element
473	// mapping at every call. 🟡 float goes through TF32 (10-bit mantissa, FP32
474	// accumulate) — the accepted FP32 tensor-core precision tradeoff, not a bug.
475	template <typename T, typename LayoutBT>
476	inline cudaError_t vit_run_gemm_bt(
477	    int M, int N, int K, const T* A, const T* B, float* C, cudaStream_t stream)
478	{
479	    if constexpr (std::is_same<T, float>::value) {
480	        return mma::sm90_run_gemm_tf32_bt<LayoutBT>(
481	            M, N, K, reinterpret_cast<const float*>(A),
482	            reinterpret_cast<const float*>(B), C, stream);
483	    } else {
484	        using Elem = typename cutlass_gemm_elem<T>::type;
485	        return mma::sm90_run_gemm_bt<Elem, LayoutBT>(M, N, K, A, B, C, stream);
486	    }
487	}
