489	template <typename T>
490	inline cudaError_t vit_run_gemm_atb(
491	    int M, int N, int K, const T* A, const T* B, float* C, cudaStream_t stream)
492	{
493	    if constexpr (std::is_same<T, float>::value) {
494	        // DOCUMENT-STOP: no TF32 A-transposed collective — CUTLASS fails a hard
495	        // static_assert ("SmemLayoutB K must be 128bytes to be transposed") for
496	        // ColumnMajor-A tfloat32_t (the RS warp-specialized transpose path; see
497	        // mma.cuh). float wgrad therefore stays on the scalar fallback: signal
498	        // not-supported so launch_gemm_grad_weight takes the scalar branch.
499	        (void)M; (void)N; (void)K; (void)A; (void)B; (void)C; (void)stream;
500	        return cudaErrorNotSupported;
501	    } else {
502	        using Elem = typename cutlass_gemm_elem<T>::type;
503	        return mma::sm90_run_gemm_atb<Elem>(M, N, K, A, B, C, stream);
504	    }
505	}
