507	// dX[M,K] = dY[M,N] · W[N,K]  (dgrad). In GEMM terms this is C[M,K]=A·B with
508	// A=dY[M,K_g=N] RowMajor and B=W physically [N,K] row-major = logical
509	// [K_g=N, N_g=K] read RowMajor → sm90_run_gemm_bt<RowMajor>(M_g=M,N_g=K,K_g=N).
510	// FP32 accumulate into scratch, then cast back into the ActT dX buffer.
511	template <typename ActT>
512	inline cudaError_t vit_dgrad_gemm(
513	    const ActT* dY, const ActT* W, ActT* dX,
514	    int M, int N, int K, cudaStream_t stream)
515	{
516	    float* c_fp32 = vit_gemm_fp32_scratch((size_t)M * K);
517	    if (c_fp32 == nullptr) return cudaErrorMemoryAllocation;
518	    cudaError_t err = vit_run_gemm_bt<ActT, cutlass::layout::RowMajor>(
519	        M, K, N, dY, W, c_fp32, stream);
520	    if (err != cudaSuccess) return err;
521	    size_t n = (size_t)M * K;
522	    int block = 256, grid = (int)((n + block - 1) / block);
523	    gemm_cast_bias_kernel<ActT, ActT><<<grid, block, 0, stream>>>(
524	        c_fp32, (const ActT*)nullptr, dX, M, K);
525	    return cudaGetLastError();
526	}
